// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 value) public {
        // Bound value to avoid overflow in burn (value must be <= balanceOf[owner] = 0)
        vm.assume(value == 0);
        address expectedOwner = c.owner();
        // Attempt to call burn — will revert due to insufficient balance (balanceOf[msg.sender] = 0)
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));
        // The rule: owner is unchanged regardless of burn's success or revert
        assertTrue(c.owner() == expectedOwner, "Owner changed after burn attempt");
    }
}

