        c.transfer(address(0), 0); // dummy to avoid unused warning
        uint256 totalSupplyBefore = c.totalSupply();
        // ensure balanceOf[msg.sender] >= _value
        vm.assume(_value <= totalSupplyBefore);
        try c.burn(_value) {
            uint256 totalSupplyAfter = c.totalSupply();
            assertTrue(totalSupplyAfter <= totalSupplyBefore);
        } catch {
            // The burn reverts if _value > balanceOf[msg.sender]; rule holds vacuously
            uint256 totalSupplyAfter = c.totalSupply();
            assertTrue(totalSupplyAfter <= totalSupplyBefore);
        }
    }
}

