pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address user1, address user2, uint256 amount1, uint256 amount2, uint256 burnAmount) public {
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2);
        vm.assume(amount1 > 0 && amount2 > 0);
        // Mint tokens to users
        c.mintToken(user1, amount1);
        c.mintToken(user2, amount2);
        uint256 totalBefore = c.totalSupply();
        uint256 balanceUser1Before = c.balanceOf(user1);
        uint256 balanceUser2Before = c.balanceOf(user2);
        uint256 sumBefore = balanceUser1Before + balanceUser2Before;
        // Burn from user1
        vm.prank(user1);
        uint256 burnVal = bound(burnAmount, 1, balanceUser1Before);
        bool success;
        try c.burn(burnVal) {
            success = true;
        } catch {
            success = false;
        }
        if (success) {
            uint256 totalAfter = c.totalSupply();
            uint256 balanceUser1After = c.balanceOf(user1);
            uint256 balanceUser2After = c.balanceOf(user2);
            uint256 sumAfter = balanceUser1After + balanceUser2After;
            assertTrue(sumAfter == totalAfter, "Sum of balances should equal total supply after burn");
        } else {
            // If burn reverts, state unchanged
            uint256 totalAfter = c.totalSupply();
            uint256 balanceUser1After = c.balanceOf(user1);
            uint256 balanceUser2After = c.balanceOf(user2);
            uint256 sumAfter = balanceUser1After + balanceUser2After;
            assertTrue(sumAfter == totalAfter, "Sum of balances should equal total supply after revert");
        }
    }
}

