pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 baseAmount, uint256 burnAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c)); // avoid self-burn edge case
        baseAmount = bound(baseAmount, 1, 1e30);
        burnAmount = bound(burnAmount, 1, baseAmount);

        // Mint tokens to caller via owner
        vm.prank(c.owner());
        c.mintToken(caller, baseAmount);

        // Record balance before burn
        uint256 balanceBefore = c.balanceOf(caller);

        // Execute burn
        vm.prank(caller);
        c.burn(burnAmount);

        // Assert: balance decreased exactly by burnAmount
        assertTrue(c.balanceOf(caller) == balanceBefore - burnAmount);
    }
}

