pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 totalSupplyInit, uint256 burnAmount, uint256 mintAmount, address mintTarget) public {
        vm.assume(burner != address(0));
        vm.assume(mintTarget != address(0));
        vm.assume(mintTarget != burner);
        vm.assume(totalSupplyInit > 0 && totalSupplyInit < 1e30);
        vm.assume(burnAmount > 0 && burnAmount <= totalSupplyInit * 1e18);
        vm.assume(mintAmount > 0 && mintAmount < 1e30);
        vm.prank(c.owner());
        c.mintToken(mintTarget, mintAmount);
        vm.prank(c.owner());
        c.mintToken(burner, totalSupplyInit * 1e18);
        vm.prank(burner);
        c.transfer(mintTarget, mintAmount);
        vm.prank(burner);
        (bool successBurn, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        vm.assume(successBurn);
        uint256 sumBalances = 0;
        address[2] memory addrs = [burner, mintTarget];
        for (uint256 i = 0; i < addrs.length; i++) {
            vm.prank(addrs[i]);
            sumBalances += c.balanceOf(addrs[i]);
        }
        assertTrue(sumBalances <= c.totalSupply());
    }
}

