pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address from, address to, uint256 amount, uint256 burnAmount) public {
        vm.assume(from != address(0) && to != address(0) && from != to);
        vm.assume(amount > 0 && amount <= 1e30);
        vm.assume(burnAmount > 0 && burnAmount <= 1e30);

        // Perform mintToken to create some supply
        vm.prank(c.owner());
        c.mintToken(from, amount);

        // Perform transfer to distribute balances
        vm.prank(from);
        c.transfer(to, amount / 2);

        // Burn some tokens
        vm.prank(c.owner());
        c.burn(burnAmount);

        // Check invariant: sum of all balances equals totalSupply
        uint256 sum;
        // We can only check the owner and the two addresses we used; for others balanceOf is 0
        sum = c.balanceOf(c.owner()) + c.balanceOf(from) + c.balanceOf(to);
        assertTrue(c.totalSupply() == sum);
    }
}

