pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, address target, uint256 mintedAmount, uint256 burnAmount) public {
        vm.assume(caller != address(0) && target != address(0));
        vm.assume(caller != target);
        vm.assume(mintedAmount <= type(uint256).max / 2);
        vm.assume(burnAmount <= mintedAmount);

        // Set up: mint some tokens
        vm.prank(c.owner());
        c.mintToken(target, mintedAmount);

        // Burn some tokens from owner
        vm.prank(c.owner());
        (bool burnSuccess, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        vm.assume(burnSuccess);

        // The invariant: totalSupply >= balanceOf of any address
        uint256 totalSup = c.totalSupply();
        uint256 maxBalance = 0;
        // We check the two addresses we know about
        uint256 balCaller = c.balanceOf(caller);
        uint256 balTarget = c.balanceOf(target);
        uint256 balOwner = c.balanceOf(c.owner());
        if (balCaller > maxBalance) maxBalance = balCaller;
        if (balTarget > maxBalance) maxBalance = balTarget;
        if (balOwner > maxBalance) maxBalance = balOwner;

        assertTrue(totalSup >= maxBalance, "totalSupply should be >= any single balance");
    }
}

