import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 amount, uint256 _value) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 1e30);
        _value = bound(_value, 0, 1e30);

        vm.prank(caller);
        try c.burn(_value) {
            // burn succeeded
        } catch {
            // burn reverted - still check the property
        }

        // After any sequence ending with burn, totalSupply >= sum of all balances
        // Since we can't iterate, we use: totalSupply >= balanceOf[owner] (owner is the only address that could have balance)
        assertTrue(c.totalSupply() >= c.balanceOf(c.owner()));
    }
}

