pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address otherUser, uint256 initialMint, uint256 burnAmount) public {
        vm.assume(otherUser != address(0) && otherUser != address(this));
        // Mint tokens to this contract and to otherUser
        vm.prank(address(this));
        c.mintToken(address(this), initialMint);
        vm.prank(address(this));
        c.mintToken(otherUser, initialMint);
        vm.assume(burnAmount > 0 && burnAmount <= initialMint);

        // Record balances and total supply before burn
        uint256 balanceThisBefore = c.balanceOf(address(this));
        uint256 balanceOtherBefore = c.balanceOf(otherUser);
        uint256 totalSupplyBefore = c.totalSupply();

        // Execute burn from this contract
        vm.prank(address(this));
        c.burn(burnAmount);

        // Rule: the decrease in total supply equals the decrease in this contract's balance
        // (since other user's balance should not change during a burn by this contract)
        uint256 balanceThisAfter = c.balanceOf(address(this));
        uint256 balanceOtherAfter = c.balanceOf(otherUser);
        uint256 totalSupplyAfter = c.totalSupply();

        assertTrue(
            (totalSupplyBefore - totalSupplyAfter) == (balanceThisBefore - balanceThisAfter) &&
            (balanceOtherAfter == balanceOtherBefore),
            "Burn should decrease total supply by exactly the amount burned from caller and not affect other balances"
        );
    }
}

