pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address addr1, address addr2, uint256 transferAmount, uint256 burnAmount) public {
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);
        // Ensure balances are sufficient
        transferAmount = bound(transferAmount, 0, 1e12);
        burnAmount = bound(burnAmount, 0, 1e12);

        // Owner mints tokens to addr1
        vm.prank(c.owner());
        c.mintToken(addr1, transferAmount + burnAmount + 1e6); // enough buffer

        // Record initial sum for addr1 and addr2
        uint256 sumBefore = c.balanceOf(addr1) + c.balanceOf(addr2);
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 initialNet = sumBefore - totalSupplyBefore;

        // Perform transfer from addr1 to addr2
        vm.prank(addr1);
        c.transfer(addr2, transferAmount);

        // Perform burn by addr1
        vm.prank(addr1);
        c.burn(burnAmount);

        // After sequence
        uint256 sumAfter = c.balanceOf(addr1) + c.balanceOf(addr2);
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 finalNet = sumAfter - totalSupplyAfter;

        // Rule: net sum decreased exactly by burnAmount (since transfer doesn't change net in reference, burn reduces net by burnAmount)
        assertTrue(finalNet == initialNet - burnAmount);
    }
}

