    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(mintAmount < 1e60);
        vm.assume(burnAmount <= mintAmount + 1e60);
        address owner = address(this);
        c.mintToken(owner, mintAmount);
        uint256 initialOwnerBalance = c.balanceOf(owner);
        uint256 initialTotalSupply = c.totalSupply();
        if (burnAmount <= initialOwnerBalance) {
            c.burn(burnAmount);
            assertTrue(c.balanceOf(owner) == initialOwnerBalance - burnAmount);
        } else {
            (bool reverted, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
            assertTrue(reverted);
        }
    }
}

