pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address target, uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(target != address(0));
        vm.assume(mintAmount > 0 && mintAmount <= type(uint256).max / 2);
        vm.assume(burnAmount > 0 && burnAmount <= mintAmount);
        c.mintToken(target, mintAmount);
        c.burn(burnAmount);
        uint256 balanceAfterBurn = c.balanceOf(target);
        vm.assume(c.owner() == address(this));
        uint256 ownerBalanceBefore = c.balanceOf(c.owner());
        // Re-deploy to have a fresh state
        setUp();
        c.mintToken(target, mintAmount);
        uint256 balanceAfterMintOnly = c.balanceOf(target);
        assertTrue(balanceAfterBurn >= balanceAfterMintOnly - mintAmount, "balance constraint violated");
    }
}

