pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 burnAmount) public {
        // restrict to avoid overflow/underflow in burn
        vm.assume(burner != address(0));
        vm.assume(burnAmount <= 1e30); // reasonable bound
        // give burner some tokens via mintToken
        c.mintToken(burner, burnAmount);
        // now burn from burner's address
        vm.prank(burner);
        // we need the burn to succeed for the balance check to be meaningful; skip if revert
        // we call burn with amount <= burner's balance (which is burnAmount)
        uint256 amountToBurn = burnAmount > 0 ? burnAmount : 0;
        // if amountToBurn == 0, burn does nothing; still valid
        // Use try/catch to handle revert (e.g., not owner? but burner is not owner; we need owner to call burn)
        // Key insight: burner is not owner, so burn will revert unless we use owner.
        // So prank as the contract owner (which is the deployer, msg.sender in setUp)
        // We need to assign burner as owner? Simpler: use the owner account (default msg.sender in setUp is address(this) in Foundry)
        // Actually owner is set to the caller of constructor. We'll prank as the contract itself (owner) from address(this)
        address owner = address(this); // because setUp was called by the test contract
        vm.prank(owner);
        // We'll call burn with amountToBurn, but require balanceOf[owner] >= amountToBurn.
        // After mintToken to burner, owner's balance is 0, so burn will revert.
        // So mintToken to owner as well
        c.mintToken(owner, 1e30); // give owner lots of tokens
        // Now burn some from owner
        uint256 burnValue = bound(burnAmount, 1, 1e29); // ensure enough balance
        c.burn(burnValue);
        // General rule: totalSupply == balanceOf[owner] + sum of balanceOf of all other addresses
        // But we can't iterate; instead we use the fact that only owner and burner have balances.
        // After mint to owner (1e30) and mint to burner (burnAmount) and burn (burnValue), 
        // totalSupply should equal balanceOf[owner] + balanceOf[burner]
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 ownerBalance = c.balanceOf(owner);
        uint256 burnerBalance = c.balanceOf(burner);
        // Additionally, any other address (e.g., random) should have 0 balance
        // Use a third address to test
        address other = address(0xdead);
        uint256 otherBalance = c.balanceOf(other);
        assertTrue(totalSupplyAfter == ownerBalance + burnerBalance + otherBalance, "Total supply mismatch");
    }
}
}

