pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burnValue) public {
        vm.assume(caller != address(0));
        vm.assume(burnValue <= type(uint256).max / 2);

        // Setup: mint some tokens to caller
        uint256 mintAmount = 1000;
        vm.prank(c.owner());
        c.mintToken(caller, mintAmount);

        uint256 balanceBefore = c.balanceOf(caller);
        uint256 supplyBefore = c.totalSupply();

        // Bound burnValue to avoid revert due to insufficient balance
        uint256 actualBurn = bound(burnValue, 0, balanceBefore);

        // Execute burn
        vm.prank(caller);
        c.burn(actualBurn);

        uint256 balanceAfter = c.balanceOf(caller);
        uint256 supplyAfter = c.totalSupply();

        // The caller's balance decrease equals the total supply decrease
        assertTrue(balanceBefore - balanceAfter == supplyBefore - supplyAfter);
    }
}

