pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 value) public {
        vm.assume(burner != address(0));
        vm.assume(value <= type(uint256).max);

        // Ensure burner is owner
        vm.prank(c.owner());
        c.transfer(burner, c.totalSupply());

        vm.prank(burner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));
        vm.assume(success);

        // General rule: no one is ever frozen
        assertTrue(!c.frozenAccount(burner) && !c.frozenAccount(address(0)) && !c.frozenAccount(address(1)));
    }
}

