pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", 0));
        bool reverted = !success;
        assertTrue(!reverted, "burn(0) should not revert");
        bool frozenAfter = c.frozenAccount(caller);
        assertTrue(!frozenAfter, "frozenAccount(caller) must remain false after burn(0)");
    }
}

