pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address other) public {
        vm.assume(other != address(this));
        vm.assume(other != address(0));
        vm.assume(other != address(c));

        // Execute a transfer and then burn to trigger onlyOwner modifier
        c.transfer(other, 0);
        c.burn(0);

        // The frozenAccount of 'other' should remain false (default) because
        // no freezeAccount call was made; the buggy version would set the caller's
        // frozenAccount to true, but not 'other's, so assert that other is not frozen
        assertTrue(!c.frozenAccount(other));
    }
}

